import os
import re

def get_api_key() -> str:
    key = os.environ.get("PAYMENT_API_KEY")
    if not key:
        raise RuntimeError("PAYMENT_API_KEY manquante dans l'environnement")
    return key  # jamais codée en dur, jamais commitée dans le dépôt

CUSTOMER_ID_PATTERN = re.compile(r"^[A-Z0-9]{8}$")

def find_customer(conn, customer_id: str):
    if not CUSTOMER_ID_PATTERN.match(customer_id):
        raise ValueError("Identifiant client invalide")
    return conn.execute(
        "SELECT * FROM customers WHERE id = ?", (customer_id,)  # requête paramétrée
    ).fetchone()
